def tau(n):
    """Calculates the number of divisors of n."""
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

N_values = [1, 2, 3, 4]
C_n_actual = [2, 2, 2, 2] # Known correct values for n=1, 2, 3, 4
formula_results = {}

for n in N_values:
    tau_n = tau(n)
    formula_result = tau_n + 1
    formula_results[n] = {
        "tau(n)": tau_n,
        "tau(n)+1": formula_result,
        "C_n_actual": C_n_actual[N_values.index(n)],
        "match": formula_result == C_n_actual[N_values.index(n)]
    }

print("N | tau(N) + 1 | C_N (Actual) | Match?")
print("-" * 40)
for n, res in formula_results.items():
    print(f"{n:2} | {res['tau(n)']} + 1 = {res['tau(n)+1']:10} | {res['C_n_actual']:12} | {res['match']}")

